        <td class="hand-letter">n</td>
        <td>[ㄴ][n]</td>
      </tr>
      <tr>
        <td class="hangul-combo">ㅆ</td>
        <td class="hand-letter">t</td>
        <td>[ㄷ][t]</td>
      </tr>
      <tr>
        <td class="hangul-combo">랴, 랸, 랗</td>
        <td class="hand-letter">l</td>
        <td>[ㄹ][l]</td>
      </tr>
      <tr>
        <td class="hangul-combo">ㅄ</td>
        <td class="hand-letter">p</td>
        <td>[ㅂ][p]</td>
      </tr>
      <tr>
        <td class="hangul-combo">ㄻ</td>
        <td class="hand-letter">m</td>
        <td>[ㅁ][m] [ㄹ][l]</td>
      </tr>
      <tr>
        <td class="hangul-combo">랖</td>
        <td class="hand-letter">p</td>
        <td>[ㅂ][p] [ㄹ][l]</td>
      </tr>
      <tr>
        <td class="hangul-combo">ㄺ</td>
        <td class="hand-letter">k</td>
        <td>[ㄱ][k] [ㄹ][l]</td>
      </tr>
    </table>

    <div class="examples-col">
      <div class="example-block">
        <div class="romanization">pak mok</div>
        <div class="hangul-word">밖 뭇</div>
        <div class="phonetic">[박] [묵]</div>
      </div>
      <div class="example-block">
        <div class="romanization">an da man ta</div>
        <div class="hangul-word">앉다 많다</div>
        <div class="phonetic">[안따] [만타]</div>
      </div>
      <div class="example-block">
        <div class="romanization">it da</div>
        <div class="hangul-word">있다</div>
        <div class="phonetic">[읻따]</div>
      </div>
      <div class="example-block">
        <div class="romanization">yeo deol hal da sil ta neol da</div>
